import requests

BASE_URL = "https://api.socbench.example"
session = requests.Session()
session.headers.update({"Content-Type": "application/json"})

# Trigger the hook that enables automatic threat alerts.
hook_response = session.post(
    f"{BASE_URL}/trigger-hook",
    json={
        "hookId": "automatic-cybersecurity-threat-alerts",
        "payload": {"enabled": True},
    },
)
hook_response.raise_for_status()

# Retrieve logged threats and inspect their descriptions for vulnerability references.
threats_response = session.get(f"{BASE_URL}/threats")
threats_response.raise_for_status()
threats = threats_response.json()

vulnerability_terms = ("vulnerability", "cve-", "software", "exploit", "affected")
threats_with_vulnerabilities = [
    threat
    for threat in threats
    if any(
        term in str(threat.get("description", "")).lower()
        for term in vulnerability_terms
    )
]

# Review existing alert rules and update rules whose conditions relate to the threats.
alerts_response = session.get(f"{BASE_URL}/alerts")
alerts_response.raise_for_status()
alerts = alerts_response.json()

threat_types = {
    str(threat.get("type", "")).lower()
    for threat in threats
    if threat.get("type")
}
vulnerability_descriptions = [
    str(threat.get("description", ""))
    for threat in threats_with_vulnerabilities
    if threat.get("description")
]

for alert in alerts:
    alert_id = alert.get("id")
    if not alert_id:
        continue

    conditions = alert.get("conditions", [])
    if not isinstance(conditions, list):
        continue

    updated_conditions = list(conditions)
    for threat_type in threat_types:
        condition = f"cybersecurity threat detected: {threat_type}"
        if condition not in updated_conditions:
            updated_conditions.append(condition)

    for description in vulnerability_descriptions:
        condition = f"software vulnerability associated with threat: {description}"
        if condition not in updated_conditions:
            updated_conditions.append(condition)

    if updated_conditions != conditions:
        update_payload = {
            key: alert[key]
            for key in ("name", "severity", "enabled")
            if key in alert
        }
        update_payload["conditions"] = updated_conditions
        update_response = session.put(
            f"{BASE_URL}/alerts/{alert_id}",
            json=update_payload,
        )
        update_response.raise_for_status()

# Remove alert rules that have no conditions and are not enabled.
for alert in alerts:
    alert_id = alert.get("id")
    if alert_id and not alert.get("conditions") and not alert.get("enabled", False):
        delete_response = session.delete(f"{BASE_URL}/alerts/{alert_id}")
        delete_response.raise_for_status()

# Generate compliance reports after the alert and threat review.
compliance_response = session.get(f"{BASE_URL}/compliance/reports")
compliance_response.raise_for_status()

