import requests

BASE_URL = "https://api.socbench.example"

template_response = requests.post(
    f"{BASE_URL}/billing/templates",
    json={
        "template_name": "Utility Usage Invoicing",
        "parameters": {
            "alert_on_unusual_usage": "true",
            "usage_monitoring": "enabled",
        },
    },
)
template_response.raise_for_status()

forecast_response = requests.get(f"{BASE_URL}/energy-output/forecast")
forecast_response.raise_for_status()
energy_forecast = forecast_response.json()

efficiency_response = requests.get(f"{BASE_URL}/efficiency-reports")
efficiency_response.raise_for_status()
efficiency_reports = efficiency_response.json()

zones_response = requests.get(f"{BASE_URL}/zones-status")
zones_response.raise_for_status()
zones = zones_response.json()

for zone in zones:
    if zone.get("priority") == "high" or zone.get("priority_level") == "high":
        zone_id = zone.get("zone_id")
        allocated_power = zone.get("recommended_allocation", zone.get("allocated_power"))
        if zone_id is not None and allocated_power is not None:
            allocation_response = requests.post(
                f"{BASE_URL}/allocate-resources",
                json={
                    "zone_id": zone_id,
                    "allocated_power": allocated_power,
                    "priority": "high",
                },
            )
            allocation_response.raise_for_status()
